#include <iostream>
#include <string>
using namespace std;

void printOrder(string order = "美式咖啡") {
    cout << order << endl;
}

int main() {
    string friendOrder;
    cin >> friendOrder;
    
    printOrder();
    printOrder(friendOrder);
    
    return 0;
}
